/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE FUNCTION `colonSeparatedHex`(hex VARCHAR(64)) RETURNS varchar(64) CHARSET utf8mb4
    DETERMINISTIC
BEGIN
    
    DECLARE i INT;
    DECLARE length INT;
    DECLARE output VARCHAR(64);

    
    SET i = 3;
    SET length = LENGTH(hex);

    
    IF MOD(length, 2) = 1 THEN
        SET hex = CONCAT('0', hex);
        SET length = length + 1;
    END IF;

    
    SET output = SUBSTR(hex, 1, 2);

    
    label: WHILE i < length DO
        SET output = CONCAT(output, ':', SUBSTR(hex, i, 2));
        SET i = i + 2;
    END WHILE label;

    
    SET output = LOWER(output);

    RETURN output;
END ;;
DELIMITER ;
